<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useAuthStore } from '../stores/auth.js'
import { useI18n } from '../composables/useI18n.js'
import { listUsers, setUserStatus, resetUserPassword, userErrorKind } from '../services/userApi.js'
import { roleLabels } from '../data/roles.js'
import UserFormDialog from '../components/users/UserFormDialog.vue'
import ConfirmDialog from '../components/users/ConfirmDialog.vue'
import TempPasswordDialog from '../components/users/TempPasswordDialog.vue'

const PAGE_SIZE = 20
const auth=useAuthStore(), {tr,language}=useI18n()
const heading=ref(null), search=ref(''), role=ref(''), status=ref(''), page=ref(1), users=ref([]), total=ref(0), totalPages=ref(0), loading=ref(false), errorKind=ref(''), activateError=ref(''), dialog=ref(''), selected=ref(null), dialogError=ref(''), actionLoading=ref(false), password=ref(''), passwordUser=ref(null), passwordReset=ref(false), announcement=ref('')
let debounceTimer, announcementTimer, requestCounter=0, controller=null, focusReturn=null
const visibleIdentifier=u=>u.role==='student'?u.studentId:u.email
const lastLogin=u=>{if(!u.lastLogin)return 'Never';const d=new Date(u.lastLogin);if(Number.isNaN(d.getTime()))return 'Date unavailable';return new Intl.DateTimeFormat(language.value==='bn'?'bn-BD':'en-GB',{dateStyle:'medium',timeStyle:'short'}).format(d)}
const pages=computed(()=>Math.max(1,totalPages.value||1))
const actionError=kind=>kind==='forbidden'?'You do not have permission to do this.':kind==='notfound'?'This user no longer exists.':kind==='validation'?'Please check the details and try again.':kind==='rate_limited'?'Too many attempts. Please wait a few minutes and try again.':kind==='network'?'Cannot reach the server. Check your connection and try again.':'Something went wrong. Please try again.'
async function fetchUsers(){const request=++requestCounter;controller?.abort();controller=new AbortController();loading.value=true;errorKind.value='';try{const data=await listUsers({role:role.value,search:search.value.trim(),isActive:status.value===''?'':status.value==='active',page:page.value,limit:PAGE_SIZE},controller.signal);if(request!==requestCounter)return;if(page.value>data.totalPages&&data.totalPages>0){page.value=data.totalPages;return}users.value=data.users||[];total.value=data.total||0;totalPages.value=data.totalPages||0;errorKind.value=''}catch(e){if(request!==requestCounter)return;const kind=userErrorKind(e);if(kind==='aborted')return;errorKind.value=kind}finally{if(request===requestCounter)loading.value=false}}
function filtersChanged(){page.value=1;fetchUsers()}
watch(search,()=>{clearTimeout(debounceTimer);debounceTimer=setTimeout(filtersChanged,400)})
watch([role,status],filtersChanged)
watch(page,()=>fetchUsers())
onMounted(fetchUsers)
onBeforeUnmount(()=>{requestCounter++;controller?.abort();clearTimeout(debounceTimer);clearTimeout(announcementTimer)})
function openDialog(kind, user=null, trigger=null){dialog.value=kind;selected.value=user;dialogError.value='';focusReturn=trigger||document.activeElement}
function closeDialog(){dialog.value='';actionLoading.value=false;selected.value=null;dialogError.value='';requestAnimationFrame(()=>{if(focusReturn?.isConnected)focusReturn.focus({preventScroll:true});else heading.value?.focus({preventScroll:true});focusReturn=null})}
function announce(text){announcement.value=text;clearTimeout(announcementTimer);announcementTimer=setTimeout(()=>announcement.value='',4000)}
function identifierFor(u){return visibleIdentifier(u)||''}
function onSaved(payload){const created=dialog.value==='create';const edited=dialog.value==='edit';closeDialog();if(created){announce('User created.');if(page.value===1)fetchUsers();else page.value=1;password.value=payload.temporaryPassword||'';passwordUser.value=payload.user;passwordReset.value=false;dialog.value='password';return}if(edited){const saved=payload.user;users.value=users.value.map(u=>u._id===saved._id?saved:u);announce('User updated.')}}
function passwordDone(){password.value='';passwordUser.value=null;closeDialog()}
async function confirmAction(){if(actionLoading.value)return;actionLoading.value=true;dialogError.value='';try{if(dialog.value==='deactivate'){const {user}=await setUserStatus(selected.value._id,false);users.value=users.value.map(u=>u._id===user._id?user:u);closeDialog();announce('User deactivated.')}else if(dialog.value==='reset'){const result=await resetUserPassword(selected.value._id);const who=selected.value;closeDialog();password.value=result.temporaryPassword||'';passwordUser.value={...result.user,...who};passwordReset.value=true;dialog.value='password'}}catch(e){const kind=userErrorKind(e);dialogError.value=actionError(kind)}finally{actionLoading.value=false}}
async function activate(user){activateError.value='';try{const {user:updated}=await setUserStatus(user._id,true);users.value=users.value.map(u=>u._id===updated._id?updated:u);announce('User activated.')}catch(e){activateError.value=actionError(userErrorKind(e))}}
function startCreate(e){openDialog('create',null,e.currentTarget)}
function startEdit(user,e){openDialog('edit',user,e.currentTarget)}
function confirmStatus(user,e){openDialog('deactivate',user,e.currentTarget)}
function confirmReset(user,e){openDialog('reset',user,e.currentTarget)}
function goPage(value){if(value>=1&&value<=pages.value)page.value=value}
const resultStart=computed(()=>total.value===0?0:(page.value-1)*PAGE_SIZE+1)
const resultEnd=computed(()=>Math.min(page.value*PAGE_SIZE,total.value))
const summaryText=computed(()=>tr('Showing X of Y users').replace('X',String(tr(resultEnd.value-resultStart.value+1))).replace('Y',String(tr(total.value))))
</script>

<template>
<section class="min-w-0" aria-labelledby="users-heading">
 <header class="mb-6 flex flex-wrap items-center justify-between gap-3"><h1 id="users-heading" ref="heading" tabindex="-1" class="text-2xl font-bold text-[#173f8e] sm:text-[28px]">{{ tr('Users') }}</h1><button type="button" class="rounded-full bg-[#294e9e] px-5 py-2.5 text-sm font-bold text-white focus-visible:outline focus-visible:outline-[3px] focus-visible:outline-[#d9b33d]" @click="startCreate">{{ tr('Create user') }}</button></header>
 <div class="mb-5 grid min-w-0 gap-3 sm:grid-cols-3"><div class="min-w-0"><label for="users-search" class="mb-1 block text-sm font-semibold">{{ tr('Search users') }}</label><input id="users-search" v-model="search" type="search" maxlength="50" class="min-h-11 w-full min-w-0 rounded-lg border border-slate-300 px-3 text-base focus-visible:outline focus-visible:outline-[3px] focus-visible:outline-[#d9b33d]" /></div><div><label for="users-role" class="mb-1 block text-sm font-semibold">{{ tr('Filter by role') }}</label><select id="users-role" v-model="role" class="min-h-11 w-full rounded-lg border border-slate-300 px-3 text-base"><option value="">{{ tr('All') }}</option><option v-for="r in ['admin','teacher','student','parent']" :key="r" :value="r">{{ tr(roleLabels[r]) }}</option></select></div><div><label for="users-status" class="mb-1 block text-sm font-semibold">{{ tr('Filter by status') }}</label><select id="users-status" v-model="status" class="min-h-11 w-full rounded-lg border border-slate-300 px-3 text-base"><option value="">{{ tr('All') }}</option><option value="active">{{ tr('Active') }}</option><option value="inactive">{{ tr('Inactive') }}</option></select></div></div>
 <p class="sr-only" aria-live="polite">{{ summaryText }}</p>
 <p v-if="announcement" role="status" aria-live="polite" class="mb-4 rounded-lg border border-emerald-300 bg-emerald-50 p-3 text-sm">{{ tr(announcement) }}</p><p v-if="activateError" role="alert" class="mb-4 rounded-lg border border-red-300 bg-red-50 p-3 text-sm text-red-800">{{ tr(activateError) }}</p>
 <p v-if="loading" role="status" class="mb-3 text-sm text-slate-600">{{ tr('Loading users…') }}</p><div v-if="errorKind" role="alert" class="rounded-lg border border-red-300 bg-red-50 p-4 text-sm text-red-800"><p>{{ tr(errorKind==='forbidden'?'You do not have permission to view users.':actionError(errorKind)) }}</p><button type="button" class="mt-3 rounded-full border px-4 py-2 font-semibold" @click="fetchUsers">{{ tr('Retry') }}</button></div>
 <p v-else-if="!loading&&!users.length" class="rounded-lg border border-slate-200 bg-white p-6 text-center">{{ tr('No users found.') }}</p>
 <template v-else>
  <div class="hidden overflow-hidden rounded-lg border border-slate-200 bg-white md:block"><table class="w-full table-fixed text-left text-sm"><caption class="sr-only">{{ tr('Users') }}</caption><thead class="bg-slate-50 text-[#173f8e]"><tr><th scope="col" class="p-3">{{ tr('Name') }}</th><th scope="col" class="p-3">{{ tr('Role') }}</th><th scope="col" class="p-3">{{ tr('Login ID') }}</th><th scope="col" class="p-3">{{ tr('Status') }}</th><th scope="col" class="p-3">{{ tr('Last login') }}</th><th scope="col" class="p-3">{{ tr('Actions') }}</th></tr></thead><tbody><tr v-for="u in users" :key="u._id" class="border-t align-top"><td class="break-words p-3 font-semibold">{{ u.name }} <span v-if="u._id===auth.user?._id" class="rounded bg-blue-50 px-1.5 py-0.5 text-xs">{{ tr('You') }}</span><span v-if="u.mustChangePassword" class="mt-1 inline-block rounded bg-amber-50 px-1.5 py-0.5 text-xs">{{ tr('Temporary password') }}</span></td><td class="p-3">{{ tr(roleLabels[u.role]||u.role) }}</td><td class="break-all p-3">{{ identifierFor(u) }}</td><td class="p-3"><span class="rounded-full border px-2 py-1 text-xs">{{ tr(u.isActive?'Active':'Inactive') }}</span></td><td class="p-3">{{ lastLogin(u)==='Never'?tr('Never'):lastLogin(u) }}</td><td class="p-3"><div class="flex flex-wrap gap-2"><button type="button" class="underline" :aria-label="tr('Edit')+' '+u.name" @click="startEdit(u,$event)">{{ tr('Edit') }}</button><template v-if="u._id!==auth.user?._id"><button v-if="u.isActive" type="button" class="underline" :aria-label="tr('Deactivate')+' '+u.name" @click="confirmStatus(u,$event)">{{ tr('Deactivate') }}</button><button v-else type="button" class="underline" :aria-label="tr('Activate')+' '+u.name" @click="activate(u)">{{ tr('Activate') }}</button><button type="button" class="underline" :aria-label="tr('Reset password')+' '+u.name" @click="confirmReset(u,$event)">{{ tr('Reset password') }}</button></template></div></td></tr></tbody></table></div>
  <ul class="grid min-w-0 gap-3 md:hidden"><li v-for="u in users" :key="u._id" class="min-w-0 rounded-lg border border-slate-200 bg-white p-4"><div class="flex flex-wrap items-start justify-between gap-2"><h2 class="break-words font-bold">{{ u.name }}</h2><span class="rounded-full border px-2 py-1 text-xs">{{ tr(u.isActive?'Active':'Inactive') }}</span></div><div class="mt-3 grid min-w-0 grid-cols-2 gap-x-3 gap-y-2 text-sm"><p><strong>{{ tr('Role') }}:</strong> {{ tr(roleLabels[u.role]||u.role) }}</p><p class="min-w-0 break-all"><strong>{{ tr('Login ID') }}:</strong> {{ identifierFor(u) }}</p><p><strong>{{ tr('Last login') }}:</strong> {{ lastLogin(u)==='Never'?tr('Never'):lastLogin(u) }}</p><p v-if="u._id===auth.user?._id">{{ tr('You') }}</p><p v-if="u.mustChangePassword">{{ tr('Temporary password') }}</p></div><div class="mt-3 flex flex-wrap gap-3"><button type="button" class="underline" :aria-label="tr('Edit')+' '+u.name" @click="startEdit(u,$event)">{{ tr('Edit') }}</button><template v-if="u._id!==auth.user?._id"><button v-if="u.isActive" type="button" class="underline" :aria-label="tr('Deactivate')+' '+u.name" @click="confirmStatus(u,$event)">{{ tr('Deactivate') }}</button><button v-else type="button" class="underline" :aria-label="tr('Activate')+' '+u.name" @click="activate(u)">{{ tr('Activate') }}</button><button type="button" class="underline" :aria-label="tr('Reset password')+' '+u.name" @click="confirmReset(u,$event)">{{ tr('Reset password') }}</button></template></div></li></ul>
  <div class="mt-4 flex flex-wrap items-center justify-between gap-3 text-sm"><span>{{ summaryText }}</span><nav :aria-label="tr('User pages')" class="flex items-center gap-2"><button type="button" :disabled="page<=1" class="rounded border px-3 py-2 disabled:opacity-40" @click="goPage(page-1)">{{ tr('Previous') }}</button><span>{{ tr('Page') }} {{ tr(page) }} / {{ tr(pages) }}</span><button type="button" :disabled="page>=pages" class="rounded border px-3 py-2 disabled:opacity-40" @click="goPage(page+1)">{{ tr('Next') }}</button></nav></div>
 </template>
 <UserFormDialog :open="dialog==='create'||dialog==='edit'" :mode="dialog==='edit'?'edit':'create'" :user="selected" :current-user-id="auth.user?._id" @saved="onSaved" @cancel="closeDialog" />
 <ConfirmDialog :open="dialog==='deactivate'||dialog==='reset'" :title="dialog==='reset'?'Reset password':'Deactivate user'" :message="dialog==='reset'?'Reset this user’s password? A new temporary password will be shown once.':'Deactivate this user? They will no longer be able to sign in.'" :confirm-label="dialog==='reset'?'Reset password':'Deactivate'" :danger="true" :loading="actionLoading" :error="dialogError" @confirm="confirmAction" @cancel="closeDialog" />
 <TempPasswordDialog :open="dialog==='password'" :name="passwordUser?.name||''" :role="passwordUser?.role||''" :identifier="passwordUser?identifierFor(passwordUser):''" :temporary-password="password" :reset="passwordReset" @done="passwordDone" />
</section>
</template>
